// Generated by bitkit from bitkit.kit.json (schema bitkit.kit/v1) at 2026-11-09T00:00:00Z. Edit the JSON, not this file.
import { WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep } from "cloudflare:workers";
import bitkit from "./generator.js";
import { handleMcp } from "./mcp.ts";
import { renderKitSite } from "./kitsite.ts";

type Tenant = { slug: string; script: string; hostname: string; owner: string; status: string; setup_hash: string | null };
type KitRecord = { id: string; slug: string; name: string; published_at: number };
const APEX = "bitkit.sh";
// The kit API and setup scripts live on app.<zone>; every other <slug>.<zone> is a tenant.
const APP = `app.${APEX}`;
export const RESERVED_SLUGS = new Set(["app", "www", "api", "admin", "mail"]);

const b32 = (bytes: Uint8Array) => {
  const a = "abcdefghijklmnopqrstuvwxyz234567";
  let bits = 0, value = 0, out = "";
  for (const byte of bytes) { value = (value << 8) | byte; bits += 8; while (bits >= 5) { out += a[(value >>> (bits - 5)) & 31]; bits -= 5; } }
  return bits > 0 ? out + a[(value << (5 - bits)) & 31] : out;
};
const hex = (buf: ArrayBuffer) => [...new Uint8Array(buf)].map((x) => x.toString(16).padStart(2, "0")).join("");
// Compares fixed-length digests so timing does not reveal how much of the token matched.
const safeEqual = async (a: string, b: string) => {
  const [x, y] = await Promise.all([a, b].map((v) => crypto.subtle.digest("SHA-256", new TextEncoder().encode(v))));
  const u = new Uint8Array(x), w = new Uint8Array(y);
  let diff = 0;
  for (let i = 0; i < u.length; i++) diff |= u[i] ^ w[i];
  return diff === 0;
};

// Builds the bundle once per kit and caches it in R2, so the checksum in the setup script always matches the bytes served.
async function bundle(env: Env, id: string): Promise<{ bytes: ArrayBuffer; sha: string; kit: KitRecord } | null> {
  if (!/^[a-z2-7]{20}$/.test(id)) return null;
  const kit = await env.REGISTRY.prepare("SELECT id, slug, name, published_at FROM kits WHERE id = ?").bind(id).first<KitRecord>();
  if (!kit) return null;
  const cached = await env.KITS.get(`kits/${id}/bundle.tar.gz`);
  if (cached) return { bytes: await cached.arrayBuffer(), sha: cached.customMetadata?.sha256 ?? "", kit };
  const source = await env.KITS.get(`kits/${id}/bitkit.kit.json`);
  if (!source) return null;
  const draft = bitkit.normalize(await source.json());
  const { files } = bitkit.generate(draft, new Date(kit.published_at));
  const tarBytes = bitkit.tar(files, kit.slug, kit.published_at);
  const bytes = await new Response(new Blob([tarBytes]).stream().pipeThrough(new CompressionStream("gzip"))).arrayBuffer();
  const sha = hex(await crypto.subtle.digest("SHA-256", bytes));
  await env.KITS.put(`kits/${id}/bundle.tar.gz`, bytes, { httpMetadata: { contentType: "application/gzip" }, customMetadata: { sha256: sha } });
  return { bytes, sha, kit };
}

async function apex(request: Request, env: Env, url: URL): Promise<Response> {
  if (url.pathname === "/api/kits" && request.method === "POST") {
    // Operators publish with the bearer token; the hosted builder publishes same-origin, rate limited per IP.
    const auth = request.headers.get("authorization") ?? "";
    const operator = auth !== "" && (await safeEqual(auth, `Bearer ${env.PUBLISH_TOKEN}`));
    if (!operator) {
      if (request.headers.get("origin") !== url.origin) return Response.json({ error: "unauthorized" }, { status: 401 });
      const ip = request.headers.get("cf-connecting-ip") ?? "unknown";
      const { success } = await env.PUBLISH_LIMIT.limit({ key: ip });
      if (!success) return Response.json({ error: "too many publishes; try again in a minute" }, { status: 429 });
    }
    const body = await request.text();
    if (body.length > 65536) return Response.json({ error: "kit too large (64 KB max)" }, { status: 413 });
    const draft = bitkit.normalize(JSON.parse(body));
    const problems = bitkit.problems(draft);
    if (problems.length) return Response.json({ error: "invalid kit", problems }, { status: 422 });
    const id = b32(crypto.getRandomValues(new Uint8Array(12))).slice(0, 20);
    const publishedAt = Date.now();
    await env.KITS.put(`kits/${id}/bitkit.kit.json`, JSON.stringify(draft), { httpMetadata: { contentType: "application/json" } });
    const key = `bk_${b32(crypto.getRandomValues(new Uint8Array(20)))}`;
    const keyHash = hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(key)));
    await env.REGISTRY.prepare("INSERT INTO kits (id, slug, name, published_at, key_hash, updated_at) VALUES (?, ?, ?, ?, ?, ?)").bind(id, draft.brand.slug, draft.brand.name, publishedAt, keyHash, publishedAt).run();
    return Response.json({ id, key, setup: `curl -fsSL ${url.origin}/setup/${id} | sh`, tarball: `${url.origin}/kits/${id}.tar.gz`, kitSite: `${url.origin}/kits/${id}/`, mcp: `${url.origin}/mcp`, publishedAt }, { status: 201 });
  }
  if (url.pathname === "/mcp") return handleMcp(request, env, url.origin);
  if ((url.pathname === "/plugin.zip" || url.pathname === "/skill.zip") && request.method === "GET") {
    const o = await env.KITS.get(`site/plugin${url.pathname}`);
    return o ? new Response(o.body, { headers: { "content-type": "application/zip", "content-disposition": `attachment; filename="bitkit-${url.pathname.slice(1)}"` } }) : new Response("Not found", { status: 404 });
  }
  const ks = url.pathname.match(/^\/kits\/([a-z2-7]{20})(\/.*)$/);
  if (ks && request.method === "GET") return kitSite(env, ks[1], ks[2], url.origin);
  let m = url.pathname.match(/^\/kits\/([a-z2-7]+)\.tar\.gz$/);
  if (m && request.method === "GET") {
    const b = await bundle(env, m[1]);
    if (!b) return new Response("Unknown kit", { status: 404 });
    return new Response(b.bytes, { headers: { "content-type": "application/gzip", "x-bitkit-sha256": b.sha, "cache-control": "public, max-age=31536000, immutable" } });
  }
  m = url.pathname.match(/^\/setup\/([a-z2-7]+)$/);
  if (m && request.method === "GET") {
    const b = await bundle(env, m[1]);
    if (!b) return new Response("echo 'bitkit: unknown kit id' >&2; exit 1\n", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
    const script = bitkit.setupScript({ id: b.kit.id, slug: b.kit.slug, name: b.kit.name, sha: b.sha, origin: url.origin });
    return new Response(script, { headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } });
  }
  if (url.pathname === "/" && request.method === "GET") {
    const page = await env.KITS.get("site/app/index.html");
    if (page) return new Response(page.body, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300", "x-content-type-options": "nosniff" } });
  }
  if (url.pathname === "/") return new Response(`bitkit: brand identity kits\n\nRun a kit's setup with:\n  curl -fsSL ${url.origin}/setup/<kit-id> | sh\n`, { headers: { "content-type": "text/plain; charset=utf-8" } });
  return new Response("Not found", { status: 404 });
}

// Kit site: the submitted Claude Design System, or the seed generated from the kit until one arrives.
async function kitSite(env: Env, id: string, path: string, origin: string, siteUrl?: string): Promise<Response> {
  if (path.startsWith("/assets/")) {
    const o = await env.KITS.get(`kits/${id}/system/project${path}`);
    return o ? new Response(o.body, { headers: { "content-type": o.httpMetadata?.contentType ?? (path.endsWith(".svg") ? "image/svg+xml" : "application/octet-stream"), "cache-control": "public, max-age=300" } }) : new Response("Not found", { status: 404 });
  }
  if (path !== "/") return Response.redirect(`${origin}/kits/${id}/`, 302);
  const manifest = await env.KITS.get(`kits/${id}/system.json`);
  let files: Record<string, string> = {}, source: "claude" | "seed" = "seed", updatedAt: string | undefined;
  if (manifest) {
    const mf = await manifest.json<{ files: string[]; at: string }>();
    for (const p of mf.files) { const o = await env.KITS.get(`kits/${id}/system/${p}`); if (o) files[p] = await o.text(); }
    source = "claude"; updatedAt = mf.at.slice(0, 10);
  } else {
    const src = await env.KITS.get(`kits/${id}/bitkit.kit.json`);
    if (!src) return new Response("Unknown kit", { status: 404 });
    const kit = bitkit.normalize(await src.json()); kit.modules = [...new Set([...kit.modules, "design-system"])];
    for (const [p, c] of Object.entries(bitkit.generate(kit).files)) if (p.startsWith("design-system/project/")) files[p.slice("design-system/".length)] = c;
  }
  return new Response(renderKitSite(files, { source, siteUrl, updatedAt }), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=60" } });
}

async function page(env: Env, key: string): Promise<Response | null> {
  const o = await env.KITS.get(key);
  return o ? new Response(o.body, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300", "x-content-type-options": "nosniff" } }) : null;
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    // app.<zone>, the apex, and workers.dev serve the kit API; every other hostname (<slug>.<zone> or an owner domain) is a tenant.
    const host = url.hostname;
    if (host === APEX) return Response.redirect(`https://www.${APEX}${url.pathname}${url.search}`, 301);
    if (host === `www.${APEX}`) return (await page(env, "site/www/index.html")) ?? Response.redirect(`https://${APP}/`, 302);
    if (host === APP || host.endsWith(".workers.dev")) return apex(request, env, url);

    // Kit sites: kit-<slug>.<zone> or kit.<owner domain>.
    const kitSlug = host.match(new RegExp(`^kit-([a-z0-9-]+)\\.${APEX.replace(".", "\\.")}$`))?.[1];
    const kitOwner = host.startsWith("kit.") ? host.slice(4) : null;
    if (kitSlug || kitOwner) {
      const t = await env.REGISTRY.prepare("SELECT t.slug, t.hostname, t.kit_id FROM tenants t LEFT JOIN tenant_hosts h ON h.slug = t.slug WHERE (t.slug = ?1 OR h.hostname = ?2) AND t.kit_id IS NOT NULL LIMIT 1").bind(kitSlug ?? "", kitOwner ?? "").first<{ slug: string; hostname: string; kit_id: string }>();
      if (t) {
        if (url.pathname.startsWith("/assets/") || url.pathname === "/") return kitSite(env, t.kit_id, url.pathname, url.origin, `https://${kitOwner ?? t.hostname}`);
        return Response.redirect(`${url.origin}/`, 302);
      }
    }

    // Dynamic Workers: preview generated code in an isolate with no outbound network.
    if (url.pathname.startsWith("/_bitkit/sandbox/")) {
      const id = url.pathname.split("/")[3];
      const row = await env.REGISTRY.prepare("SELECT code FROM snippets WHERE id = ?").bind(id).first<{ code: string }>();
      if (!row) return new Response("Unknown snippet", { status: 404 });
      const worker = env.LOADER.get(`snippet:${id}`, async () => ({
        compatibilityDate: "2026-11-08",
        mainModule: "main.js",
        modules: { "main.js": row.code },
        globalOutbound: null,
      }));
      return worker.getEntrypoint().fetch(request);
    }

    // Tenant routing: <slug>.bitkit.sh plus any custom hostnames mapped in tenant_hosts.
    const tenant = await env.REGISTRY.prepare("SELECT t.* FROM tenants t LEFT JOIN tenant_hosts h ON h.slug = t.slug WHERE (t.hostname = ?1 OR h.hostname = ?1) AND t.status = 'active' LIMIT 1").bind(host).first<Tenant>();
    if (!tenant) return new Response("No site here yet", { status: 404 });

    // EmDash's first-run setup makes the first visitor the admin, so the platform gates it:
    // only a browser holding the owner's one-time setup cookie reaches the setup routes.
    const setupPath = url.pathname.startsWith("/_emdash/admin/setup") || (url.pathname.startsWith("/_emdash/api/setup") && url.pathname !== "/_emdash/api/setup/status");
    if (url.pathname === "/_bitkit/setup") {
      const token = url.searchParams.get("token") ?? "";
      if (!tenant.setup_hash || hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token))) !== tenant.setup_hash) return new Response("This setup link is not valid.", { status: 403 });
      return new Response(null, { status: 302, headers: { location: "/_emdash/admin", "set-cookie": `bitkit_setup=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=86400` } });
    }
    if (setupPath) {
      const cookie = request.headers.get("cookie")?.match(/(?:^|;\s*)bitkit_setup=([^;]+)/)?.[1] ?? "";
      const okSetup = tenant.setup_hash && hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(cookie))) === tenant.setup_hash;
      if (!okSetup) return new Response("Setup is reserved for the site owner. Open the setup link bitkit sent you.", { status: 403, headers: { "content-type": "text/plain; charset=utf-8" } });
    }
    try {
      return await env.TENANTS.get(tenant.script).fetch(request);
    } catch (e) {
      if (e instanceof Error && e.message.startsWith("Worker not found")) return new Response("Site is being set up", { status: 503 });
      throw e;
    }
  },
} satisfies ExportedHandler<Env>;

// Provisions one tenant from a bitkit.kit.json. Each step is retried on its own.
// Creates resources in the PLATFORM account, never in the owner's, and never
// creates social or registrar accounts.
type ProvisionParams = { kit: { brand: { slug: string; name: string }; services: string[] } };
export class ProvisionTenant extends WorkflowEntrypoint<Env, ProvisionParams> {
  async run(event: WorkflowEvent<ProvisionParams>, step: WorkflowStep) {
    const { kit } = event.payload;
    if (RESERVED_SLUGS.has(kit.brand.slug)) throw new Error(`slug ${kit.brand.slug} is reserved`);
    const slug = kit.brand.slug, script = `tenant-${slug}`, hostname = `${slug}.${this.env.PLATFORM_ZONE}`;
    const api = (path: string, init: RequestInit = {}) =>
      fetch(`https://api.cloudflare.com/client/v4/accounts/${this.env.CF_ACCOUNT_ID}${path}`, {
        ...init,
        headers: { authorization: `Bearer ${this.env.CF_PLATFORM_TOKEN}`, "content-type": "application/json" },
      }).then(async (r) => { const j = await r.json<{ success: boolean; errors: unknown; result: any }>(); if (!j.success) throw new Error(JSON.stringify(j.errors)); return j.result; });

    const resources = await step.do("create resources", async () => {
      const out: Record<string, string> = {};
      if (kit.services.includes("kv")) out.kv = (await api("/storage/kv/namespaces", { method: "POST", body: JSON.stringify({ title: `${slug}-cache` }) })).id;
      if (kit.services.includes("d1")) out.d1 = (await api("/d1/database", { method: "POST", body: JSON.stringify({ name: `${slug}-db` }) })).uuid;
      if (kit.services.includes("r2")) { await api("/r2/buckets", { method: "POST", body: JSON.stringify({ name: `${slug}-media` }) }); out.r2 = `${slug}-media`; }
      return out;
    });
    await step.do("register tenant", async () => {
      await this.env.REGISTRY.prepare("INSERT OR REPLACE INTO tenants (slug, script, hostname, owner, status, resources) VALUES (?, ?, ?, ?, 'pending', ?)")
        .bind(slug, script, hostname, "", JSON.stringify(resources)).run();
    });
    // The tenant's code is deployed with `npx cf@latest deploy --dispatch-namespace bitkit-tenants`, then activated here.
    await step.waitForEvent("tenant deployed", { type: "tenant-deployed", timeout: "7 days" });
    await step.do("activate", async () => {
      await this.env.REGISTRY.prepare("UPDATE tenants SET status = 'active' WHERE slug = ?").bind(slug).run();
    });
    return { slug, hostname, resources };
  }
}
